  DELETED_WORKSPACE_RETENTION_DAYS * 24 * 60 * 60 * 1000;

/**
 * True once a deleted org's grace period is over at `now`: it can no longer
 * be restored and the retention sweep may purge it. Always false for a live
 * org.
 */
export function isPastDeletionWindow(org: Organization, now: Date): boolean {
  if (org.archivedAt === null) return false;
  const deletedAt = new Date(org.archivedAt).getTime();
  return now.getTime() - deletedAt >= DELETED_WORKSPACE_RETENTION_MS;
}

/**
 * Deletion is a soft delete guarded by a typed confirmation, the same shape
 * GitHub uses: the caller has to retype the slug. The org then sits inert for
 * `DELETED_WORKSPACE_RETENTION_DAYS`, restorable by an owner, before the
 * retention sweep purges it.
 */''')
sub(p, '''  return orgRepo.archiveOrg(input.orgId);
