import { resolveActorForOrg } from "@/server/services/session-service";
import { createTenant, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import type { OrgId } from "@/types/common";

const MS_PER_DAY = 24 * 60 * 60 * 1000;
const WINDOW_MS = DELETED_WORKSPACE_RETENTION_DAYS * MS_PER_DAY;

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(subscribe(type, (payload) => void seen.push(payload)));
  return seen;
}

async function remove(tenant: Tenant) {
  return orgService.deleteOrganization(tenant.actors.owner, {
    orgId: tenant.org.id,
    confirmSlug: tenant.org.slug,
  });
}

function principal(tenant: Tenant) {
  return {
    userId: tenant.userIds.owner,
    email: "owner@example.test",
    activeOrgId: null,
    expiresAt: "2999-01-01T00:00:00.000Z" as never,
  };
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  cleanup();
});

describe("deleting a workspace", () => {
  it("publishes organization.deleted, audits it and refuses a second delete", async () => {
    const tenant = await createTenant("lc-delete");
    detachers.push(registerActivityListeners());
    const seen = capture("organization.deleted");

    const deleted = await remove(tenant);

    expect(deleted.archivedAt).not.toBeNull();
    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.owner,
      slug: "lc-delete",
    });

    const audit = await activityRepo.listActivity({
      orgId: tenant.org.id,
      action: ["organization.deleted"],
      limit: 10,
      cursor: null,
    });
    expect(audit.items).toHaveLength(1);
    expect(audit.items[0]).toMatchObject({
      subjectKind: "organization",
      subjectId: tenant.org.id,
      actorId: tenant.userIds.owner,
    });

    await expect(remove(tenant)).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("leaves the workspace inert but its slug reserved", async () => {
    const tenant = await createTenant("lc-inert");
    const invitee = await userRepo.insertUser({
      email: "invitee@lc-inert.test",
      name: "Invitee",
      passwordHash: "seed",
    });
    await invitationRepo.insertInvitation(
      tenant.org.id,
      { orgId: tenant.org.id, email: invitee.email, role: "member", expiresInDays: 14 },
      tenant.userIds.owner,
      hashToken("lc-inert-token"),
    );

    await remove(tenant);

    expect(await resolveActorForOrg(principal(tenant), "lc-inert")).toBeNull();
    expect(await orgService.listOrganizationsForUser(tenant.userIds.owner)).toEqual([]);
    expect(await orgRepo.listTakenOrgSlugs("lc-inert")).toContain("lc-inert");

    expect(
      await notify(tenant.org.id, "issue_assigned", [tenant.userIds.member], {
        title: "t",
        body: "b",
        href: "/",
        actorId: null,
      }),
    ).toEqual([]);

    await expect(
      acceptInvitation(invitee.id, { token: "lc-inert-token" }),
    ).rejects.toBeInstanceOf(NotFoundError);
    expect(await invitationRepo.countPendingInvitations(tenant.org.id)).toBe(1);

    await usageRepo.recomputeUsage(tenant.org.id);
    expect(await usageRepo.listOrgIdsForRollup(100)).not.toContain(tenant.org.id);
  });
});

describe("restoring a workspace", () => {
  it("is owner-only, hidden from strangers, and brings the workspace back", async () => {
    const tenant = await createTenant("lc-restore");
    const stranger = await createTenant("lc-stranger");
    await remove(tenant);
    const seen = capture("organization.restored");

    await expect(
      orgService.restoreOrganization(tenant.userIds.owner, "missing" as OrgId),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      orgService.restoreOrganization(stranger.userIds.owner, tenant.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      orgService.restoreOrganization(tenant.userIds.admin, tenant.org.id),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    expect(seen).toHaveLength(0);

    const restored = await orgService.restoreOrganization(
      tenant.userIds.owner,
      tenant.org.id,
    );

    expect(restored.archivedAt).toBeNull();
    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({ actorId: tenant.userIds.owner, slug: "lc-restore" });
    expect(await resolveActorForOrg(principal(tenant), "lc-restore")).not.toBeNull();

    // Restoring a live workspace is a no-op.
    await orgService.restoreOrganization(tenant.userIds.owner, tenant.org.id);
    expect(seen).toHaveLength(1);
  });

  it("is refused once the window has closed, even before the purge runs", async () => {
    const tenant = await createTenant("lc-late");
    const deleted = await remove(tenant);

    vi.useFakeTimers({ toFake: ["Date"] });
    try {
      vi.setSystemTime(new Date(deleted.archivedAt as string).getTime() + WINDOW_MS);
      await expect(
        orgService.restoreOrganization(tenant.userIds.owner, tenant.org.id),
      ).rejects.toBeInstanceOf(NotFoundError);
    } finally {
      vi.useRealTimers();
    }
  });
});

describe("the retention sweep", () => {
  it("purges only workspaces deleted at least the window ago", async () => {
    const gone = await createTenant("lc-purge");
    const live = await createTenant("lc-live");
    const deleted = await remove(gone);
    const deletedAt = new Date(deleted.archivedAt as string).getTime();

    await runCleanupArchivedJob(new Date(deletedAt + WINDOW_MS - 1));
    expect(await orgRepo.findOrgById(gone.org.id)).not.toBeNull();

    await runCleanupArchivedJob(new Date(deletedAt + WINDOW_MS));

    expect(await orgRepo.findOrgById(gone.org.id)).toBeNull();
    expect(await orgRepo.findOrgById(live.org.id)).not.toBeNull();

    const db = getDb();
    expect(db.select().from(members).where(eq(members.orgId, gone.org.id)).all()).toEqual([]);
    expect(db.select().from(projects).where(eq(projects.orgId, gone.org.id)).all()).toEqual([]);
    expect(db.select().from(members).where(eq(members.orgId, live.org.id)).all()).toHaveLength(4);
    expect(await userRepo.findUserById(gone.userIds.owner)).not.toBeNull();

    await expect(
      orgService.restoreOrganization(gone.userIds.owner, gone.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    const reborn = await orgService.createOrganization(gone.userIds.owner, {
      name: "Reborn",
      slug: "lc-purge",
      plan: "free",
    });
    expect(reborn.slug).toBe("lc-purge");
  });
});
EOF
